class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        count = Counter(nums)
        buckets: list[list[int]] = [[] for _ in range(len(nums) + 1)]
        for x, c in count.items():
            buckets[c].append(x)  # viz:bucket
        top: list[int] = []
        for c in range(len(nums), 0, -1):
            for x in buckets[c]:
                top.append(x)  # viz:take
                if len(top) == k:
                    return top  # viz:done
        return top
